// --- 1. ARCHITECTURE DEFINITIONS ---
// These match your manually set values in the gem5 Python script
#define HW_ROWS 32
#define HW_COLS 6

// --- 2. LAYER DATA ---
// These headers were generated by your PyTorch extraction script
#include "input_image.h"
#include "weights_l1.h"
#include "weights_l2.h"
#include "bias_l1.h"
#include "bias_l2.h"

// --- 3. REGISTER MAP ---
#define REG_CMD 0x00
#define REG_STATUS 0x04
#define REG_PREC_W 0x08
#define REG_PREC_I 0x0C
#define REG_W_ADDR 0x10
#define REG_W_LEN 0x18
#define REG_I_ADDR 0x20
#define REG_I_LEN 0x28
#define REG_OUT_ADDR 0x30
#define REG_SIGN 0x34

#define CMD_COMPUTE 1
#define CMD_LOAD_W 2
#define CMD_LOAD_I 3
#define CMD_STORE_O 4

struct imc_ioctl_args
{
    uint64_t va_addr;
    uint64_t pa_addr;
};
volatile uint32_t *imc_regs = nullptr;
int driver_fd = -1;

// --- 4. DRIVER & PHYSICAL ADDRESS HELPERS ---
// This helper talks to the Linux driver to translate a pointer (like where your weights are in RAM) into a physical
// address the IMC hardware can actually find.
uint64_t get_pa(void *va)
{
    imc_ioctl_args args = {(uint64_t)va, 0};
    if (ioctl(driver_fd, 0xCAFE, &args) < 0)
    {
        perror("IOCTL Physical Address Translation Failed");
        exit(1);
    }
    return args.pa_addr;
}

void wait_idle()
{
    while (imc_regs[REG_STATUS / 4] != 0)
    { /* Polling */
    }
}

// --- 5. ACTIVATION & VERIFICATION ---
void relu_activation(std::vector<int32_t> &data)
{
    for (auto &val : data)
        if (val < 0)
            val = 0;
}

