// --- UPDATED VERIFICATION ENGINE ---
bool verify_results(const std::vector<int32_t> &hw_results,
                    const int8_t *weights, const int8_t *bias,
                    const int8_t *inputs, int rows, int cols)
{
    printf("\n--- Detailed Comparison: HW vs. Golden Reference ---\n");
    printf("%-10s | %-12s | %-12s | %-8s\n", "Output ID", "Hardware", "Golden", "Match?");
    printf("----------------------------------------------------------\n");

    int errors = 0;
    // We will print the first 10 results for visual confirmation
    int display_limit = (cols < 10) ? cols : 10;
    int current_prec = 4;
    for (int c = 0; c < cols; c++)
    {
        int64_t golden_sum = (int64_t)bias[c];

        for (int r = 0; r < rows; r++)
        {
            // 1. Get the original 8-bit weight from the header
            int8_t w8 = weights[c * rows + r];

            // 4. Multiply using the "broken" 4-bit weight
            golden_sum += (int64_t)inputs[r] * w8;
        }

        bool match = (hw_results[c] == (int32_t)golden_sum);

        // Print detailed info for the first few outputs
        if (c < display_limit)
        {
            printf("Col [%02d]  | %-12d | %-12ld | %-8s\n",
                   c, hw_results[c], golden_sum, match ? "YES" : "FIXME");
        }

        if (!match)
            errors++;
    }

    if (errors == 0)
    {
        printf("----------------------------------------------------------\n");
        printf(">>> FINAL STATUS: 100%% BIT-ACCURATE MATCH (%d/%d) <<<\n", cols, cols);
        return true;
    }
    else
    {
        printf("----------------------------------------------------------\n");
        printf(">>> ERROR: %d mismatches detected! Check your sign extension. <<<\n", errors);
        return false;
    }
}

// --- 6. GENERIC INFERENCE ENGINE ---
std::vector<int32_t> run_layer(const char *name, const int8_t *weights, const int8_t *bias, const int8_t *inputs,
                               int layer_in, int layer_out, bool is_signed)
{
    printf("\n>>> Executing Layer: %s (%d In -> %d Out) <<<\n", name, layer_in, layer_out);

    // Setup precision and signing
    imc_regs[REG_SIGN / 4] = is_signed ? 1 : 0;
    imc_regs[REG_PREC_I / 4] = 8;
    imc_regs[REG_PREC_W / 4] = 8;

    std::vector<int32_t> results(layer_out, 0);
    std::vector<int32_t> tile_buf(HW_COLS, 0);
    uint64_t p_tile_out = get_pa(tile_buf.data());

    // Tiling Loops
    for (int k_tile = 0; k_tile < (layer_out + HW_COLS - 1) / HW_COLS; k_tile++) // output channels
    {
        for (int c_tile = 0; c_tile < (layer_in + HW_ROWS - 1) / HW_ROWS; c_tile++) // inputs that are passsed to the IMC
        {

            int k_start = k_tile * HW_COLS;
            int c_start = c_tile * HW_ROWS;

            // Pack Weights into Hardware Tile
            std::vector<int8_t> w_tile(HW_ROWS * HW_COLS, 0);
            for (int r = 0; r < HW_ROWS; r++)
            {
                for (int c = 0; c < HW_COLS; c++)
                {
                    int r_idx = c_start + r;
                    int c_idx = k_start + c;
                    if (r_idx < layer_in && c_idx < layer_out)
                        w_tile[r * HW_COLS + c] = weights[c_idx * layer_in + r_idx];
                }
            }

            // DMA Weight & Input
            imc_regs[REG_W_ADDR / 4] = get_pa(w_tile.data());
            imc_regs[REG_W_LEN / 4] = w_tile.size();
            imc_regs[REG_CMD / 4] = CMD_LOAD_W;
            wait_idle();

            std::vector<int8_t> i_slice(HW_ROWS, 0);
            for (int i = 0; i < HW_ROWS; i++)
                if (c_start + i < layer_in)
                    i_slice[i] = inputs[c_start + i];
            imc_regs[REG_I_ADDR / 4] = get_pa(i_slice.data());
            imc_regs[REG_I_LEN / 4] = i_slice.size();
            imc_regs[REG_CMD / 4] = CMD_LOAD_I;
            wait_idle();

            // Compute
            imc_regs[REG_CMD / 4] = CMD_COMPUTE;
            wait_idle();

            // Store & Accumulate
            imc_regs[REG_OUT_ADDR / 4] = p_tile_out;
            imc_regs[REG_CMD / 4] = CMD_STORE_O;
            wait_idle();

            for (int c = 0; c < HW_COLS; c++)
            {
                if (k_start + c < layer_out)
                    results[k_start + c] += tile_buf[c];
            }
        }
    }

    // After the tiling loops are finished, your 'results' vector contains the W*x sums.
    // Now, add the bias to each output neuron.
    for (int c = 0; c < layer_out; c++)
    {
        results[c] += bias[c];
    }

    verify_results(results, weights, bias, inputs, layer_in, layer_out);
    return results;
}

// --- 7. MAIN INFERENCE PIPELINE ---
int main()
{
    driver_fd = open("/dev/imc", O_RDWR);
    imc_regs = (uint32_t *)mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, driver_fd, 0);

    // Pass 1: FC1 (784 -> 64)
    std::vector<int32_t> l1_out = run_layer("MNIST_FC1", w_l1, b_l1, img_input, 784, 64, true);

    // Activation & Re-quantization
    relu_activation(l1_out);
    std::vector<int8_t> next_in(l1_out.size());
    for (size_t i = 0; i < l1_out.size(); ++i)
        next_in[i] = (int8_t)std::clamp(l1_out[i], 0, 127);

    // Pass 2: FC2 (64 -> 10)
    std::vector<int32_t> scores = run_layer("MNIST_FC2", w_l2, b_l2, next_in.data(), 64, 10, true);

    // Final Prediction
    int digit = std::distance(scores.begin(), std::max_element(scores.begin(), scores.end()));
    printf("\n*** FINAL PREDICTION: %d ***\n", digit);

    close(driver_fd);
    return 0;
}